 if(/tử hồn|linh hồn|hỏa đạn|đất nén|bắc minh|mạch lôi|điện tích|nhận\s+\d+\s+(?:tầng|điểm|hồn|đạn|phiến)[^.;]{0,40}tối đa/.test(t))return'SELF_STACK';
